CREATE TABLE `users` (
  `id` VARCHAR(36) NOT NULL,
  `full_name` VARCHAR(100) NOT NULL,
  `profile_picture_url` VARCHAR(500) DEFAULT NULL,
  `email` VARCHAR(255) NOT NULL,
  `phone_number` VARCHAR(20) NOT NULL,
  `password` VARCHAR(255) NOT NULL,
  `role` ENUM('user', 'admin') DEFAULT 'user',
  `is_active` TINYINT(1) DEFAULT 1,
  `apex_coins` DECIMAL(20,8) DEFAULT 0.00000000,
  `account_balance` DECIMAL(20,8) DEFAULT 0.00000000,
  `p2p_wallet` DECIMAL(20,8) DEFAULT 0.00000000,
  `locked_apex_coins` DECIMAL(20,8) DEFAULT 0.00000000,
  `lock_start_date` DATETIME DEFAULT NULL,
  `lock_end_date` DATETIME DEFAULT NULL,
  `last_lock_date` DATETIME DEFAULT NULL,
  `total_roi_earned` DECIMAL(20,8) DEFAULT 0.00000000,
  `total_bonus_earned` DECIMAL(20,8) DEFAULT 0.00000000,
  `total_profit_share_earned` DECIMAL(20,8) DEFAULT 0.00000000,
  `p2p_system_fees` DECIMAL(20,8) DEFAULT 0.00000000,
  `withdrawal_system_fees` DECIMAL(20,8) DEFAULT 0.00000000,
  `last_profit_share_claim_dates` JSON NOT NULL,
  `is_verified` TINYINT(1) DEFAULT 0,
  `otp` VARCHAR(10) DEFAULT NULL,
  `otp_expiry` DATETIME DEFAULT NULL,
  `referral_code` VARCHAR(20) DEFAULT NULL,
  `referred_by` VARCHAR(36) DEFAULT NULL,
  `referrals` JSON NOT NULL,
  `referral_chain` JSON NOT NULL,
  `last_login` DATETIME DEFAULT NULL,
  `created_at` DATETIME NOT NULL,
  `updated_at` DATETIME NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `users_email` (`email`),
  UNIQUE KEY `users_phone_number` (`phone_number`),
  UNIQUE KEY `users_referral_code` (`referral_code`),
  KEY `users_referred_by` (`referred_by`),
  KEY `users_is_active` (`is_active`),
  KEY `users_role` (`role`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `locked_coins_entries` (
  `id` VARCHAR(36) NOT NULL,
  `user_id` VARCHAR(36) NOT NULL,
  `amount` DECIMAL(20,8) NOT NULL,
  `lock_start_date` DATETIME NOT NULL,
  `lock_end_date` DATETIME NOT NULL,
  `status` ENUM('active', 'completed', 'unlock-pending', 'unlocked') DEFAULT 'active',
  `roi_rate_at_lock` DECIMAL(10,4) NOT NULL DEFAULT 0.0000,
  `unlock_requested_at` DATETIME DEFAULT NULL,
  `unlock_process_after` DATETIME DEFAULT NULL,
  `penalty_percentage` DECIMAL(5,2) DEFAULT 0.00,
  `penalty_amount` DECIMAL(20,8) DEFAULT 0.00000000,
  `amount_after_penalty` DECIMAL(20,8) DEFAULT 0.00000000,
  `days_elapsed_at_request` INT DEFAULT 0,
  `unlock_approved_at` DATETIME DEFAULT NULL,
  `unlock_approved_by` VARCHAR(36) DEFAULT NULL,
  `unclaimed_profit` DECIMAL(20,8) DEFAULT 0.00000000,
  `last_claim_date` DATETIME DEFAULT NULL,
  `total_claimed_profit` DECIMAL(20,8) DEFAULT 0.00000000,
  `created_at` DATETIME NOT NULL,
  `updated_at` DATETIME NOT NULL,
  PRIMARY KEY (`id`),
  KEY `locked_coins_entries_user_id` (`user_id`),
  KEY `locked_coins_entries_status` (`status`),
  KEY `locked_coins_entries_user_id_status` (`user_id`, `status`),
  KEY `locked_coins_entries_lock_start_date` (`lock_start_date`),
  KEY `locked_coins_entries_lock_end_date` (`lock_end_date`),
  CONSTRAINT `locked_coins_entries_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `locked_coins_entries_ibfk_2` FOREIGN KEY (`unlock_approved_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `apex_coin_rates` (
  `id` VARCHAR(36) NOT NULL,
  `rate` DECIMAL(20,8) NOT NULL DEFAULT 1.00000000,
  `is_active` TINYINT(1) DEFAULT 1,
  `created_by` VARCHAR(36) DEFAULT NULL,
  `created_at` DATETIME NOT NULL,
  `updated_at` DATETIME NOT NULL,
  PRIMARY KEY (`id`),
  KEY `apex_coin_rates_is_active` (`is_active`),
  KEY `apex_coin_rates_created_at` (`created_at`),
  CONSTRAINT `apex_coin_rates_ibfk_1` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `roi_rates` (
  `id` VARCHAR(36) NOT NULL,
